syntax:
CREATE FUNCTION trigger_function_name() RETURNS TRIGGER AS $$
BEGIN
    IF NEW.column < 0 THEN
        RAISE EXCEPTION 'reason for rejecting this write';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_name
    BEFORE UPDATE ON table_name
    FOR EACH ROW
    EXECUTE FUNCTION trigger_function_name();

example:
CREATE FUNCTION reject_negative_price() RETURNS TRIGGER AS $$
BEGIN
    IF NEW.price < 0 THEN
        RAISE EXCEPTION 'price cannot be negative';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_reject_negative_price
    BEFORE UPDATE ON products
    FOR EACH ROW
    EXECUTE FUNCTION reject_negative_price();

